      await db.execute(sql.raw(`DELETE FROM enquire_data WHERE mapped_location_id IN (SELECT id FROM locations WHERE client_id = 'demo')`));
      await db.execute(sql.raw(`DELETE FROM locations WHERE client_id = 'demo'`));
