  // POST /api/admin/backfill-companion-room-type
  // Corrects historical rent_roll_data and rent_roll_history rows where room_type
  // was stored as a non-canonical companion variant (e.g., "Companion Suite",
  // "Companion Room") instead of the standard "Companion".
  //
  // Note: Records incorrectly stored as "Studio" due to the parseBedTypeDesc bug
  // (where source BedTypeDesc started with "Compan" but size was not captured)
  // cannot be retroactively identified because the raw BedTypeDesc source value
  // is not persisted in any database column. Those records require re-upload from
  // the original source files. This endpoint corrects all other identifiable cases.
  //
  // Safe to run multiple times (idempotent).
  app.post('/api/admin/backfill-companion-room-type', async (req, res) => {
    try {
      console.log('Running Companion room type backfill...');

      // Pre-check: count rows with non-canonical companion variants
      const preCheckResult = await db.execute(sql`
        SELECT
          (SELECT count(*)::int FROM rent_roll_data WHERE lower(room_type) LIKE '%compan%' AND room_type != 'Companion') AS rent_roll_data_pre,
          (SELECT count(*)::int FROM rent_roll_history WHERE lower(room_type) LIKE '%compan%' AND room_type != 'Companion') AS rent_roll_history_pre
      `);
      const preCheck = preCheckResult.rows[0] as any;
      console.log(`Pre-backfill: rent_roll_data=${preCheck?.rent_roll_data_pre}, rent_roll_history=${preCheck?.rent_roll_history_pre}`);

      const rentRollResult = await db.execute(sql`
        WITH updated AS (
          UPDATE rent_roll_data
          SET room_type = 'Companion'
          WHERE lower(room_type) LIKE '%compan%'
            AND room_type != 'Companion'
          RETURNING id
        )
        SELECT count(*)::int AS rows_updated FROM updated
      `);

      const historyResult = await db.execute(sql`
        WITH updated AS (
          UPDATE rent_roll_history
          SET room_type = 'Companion'
          WHERE lower(room_type) LIKE '%compan%'
            AND room_type != 'Companion'
          RETURNING id
        )
        SELECT count(*)::int AS rows_updated FROM updated
      `);

      const rentRollUpdated = (rentRollResult.rows[0] as any)?.rows_updated ?? 0;
      const historyUpdated = (historyResult.rows[0] as any)?.rows_updated ?? 0;

      console.log(`Companion backfill complete: rent_roll_data=${rentRollUpdated}, rent_roll_history=${historyUpdated}`);

      res.json({
        success: true,
        rentRollDataRowsUpdated: rentRollUpdated,
        rentRollHistoryRowsUpdated: historyUpdated,
        preCheckCounts: {
          rentRollDataAffected: preCheck?.rent_roll_data_pre ?? 0,
          rentRollHistoryAffected: preCheck?.rent_roll_history_pre ?? 0,
        },
        message: `Backfill complete. Updated ${rentRollUpdated} rent_roll_data rows and ${historyUpdated} rent_roll_history rows.`
      });
    } catch (error) {
      console.error('Error running Companion room type backfill:', error);
      res.status(500).json({ error: 'Failed to run Companion room type backfill' });
    }
  });

  // POST /api/admin/backfill-location-ids
  // One-time backfill: for rent_roll_data and rent_roll_history rows that have a non-null
  // location name but a null location_id, attempt to match the name against the locations
  // table and update the row. This ensures group-average days-vacant keys are ID-based
  // (stable) rather than name-string-based (fragile across name variations).
  app.post('/api/admin/backfill-location-ids', async (req, res) => {
    try {
      console.log('Running location_id backfill for rent_roll_data and rent_roll_history...');

      const preCheckResult = await db.execute(sql`
        SELECT
          (SELECT count(*)::int FROM rent_roll_data    WHERE location_id IS NULL AND location IS NOT NULL AND location != '') AS data_null_pre,
          (SELECT count(*)::int FROM rent_roll_history WHERE location_id IS NULL AND location IS NOT NULL AND location != '') AS history_null_pre
      `);
      const preCheck = preCheckResult.rows[0] as any;
      console.log(`Pre-backfill: rent_roll_data=${preCheck?.data_null_pre}, rent_roll_history=${preCheck?.history_null_pre}`);

      // Pass 1: exact name match
      const dataResult = await db.execute(sql`
        WITH updated AS (
          UPDATE rent_roll_data rrd
          SET location_id = loc.id
          FROM locations loc
          WHERE rrd.location_id IS NULL
            AND rrd.location IS NOT NULL
            AND rrd.location != ''
            AND lower(rrd.location) = lower(loc.name)
            AND (rrd.client_id = loc.client_id OR loc.client_id IS NULL)
          RETURNING rrd.id
        )
        SELECT count(*)::int AS rows_updated FROM updated
      `);

      const historyResult = await db.execute(sql`
        WITH updated AS (
          UPDATE rent_roll_history rrh
          SET location_id = loc.id
          FROM locations loc
          WHERE rrh.location_id IS NULL
            AND rrh.location IS NOT NULL
            AND rrh.location != ''
            AND lower(rrh.location) = lower(loc.name)
          RETURNING rrh.id
        )
        SELECT count(*)::int AS rows_updated FROM updated
      `);

      const dataUpdated = (dataResult.rows[0] as any)?.rows_updated ?? 0;
      const historyUpdated = (historyResult.rows[0] as any)?.rows_updated ?? 0;
      console.log(`Pass 1 (name match): rent_roll_data=${dataUpdated}, rent_roll_history=${historyUpdated}`);

      // Pass 2: location-code match — extract embedded numeric code from location strings
      // e.g. "Sylvania KSL-0560" -> "0560" (or 3-digit variant "KSL-560" -> "0560")
      // then match against locations.location_code (stored as zero-padded 4 digits)
      const dataCodeResult = await db.execute(sql`
        WITH updated AS (
          UPDATE rent_roll_data rrd
          SET location_id = loc.id
          FROM locations loc
          WHERE rrd.location_id IS NULL
            AND rrd.location IS NOT NULL
            AND rrd.location != ''
            AND loc.location_code IS NOT NULL
            AND loc.location_code != ''
            AND lpad(substring(rrd.location from '[A-Za-z]+-(\d{3,4})'), 4, '0') = loc.location_code
            AND (rrd.client_id = loc.client_id OR loc.client_id IS NULL)
          RETURNING rrd.id
        )
        SELECT count(*)::int AS rows_updated FROM updated
      `);

      const historyCodeResult = await db.execute(sql`
        WITH updated AS (
          UPDATE rent_roll_history rrh
          SET location_id = loc.id
          FROM locations loc
          WHERE rrh.location_id IS NULL
            AND rrh.location IS NOT NULL
            AND rrh.location != ''
            AND loc.location_code IS NOT NULL
            AND loc.location_code != ''
            AND lpad(substring(rrh.location from '[A-Za-z]+-(\d{3,4})'), 4, '0') = loc.location_code
            AND (rrh.client_id = loc.client_id OR loc.client_id IS NULL)
          RETURNING rrh.id
        )
        SELECT count(*)::int AS rows_updated FROM updated
      `);

      const dataCodeUpdated = (dataCodeResult.rows[0] as any)?.rows_updated ?? 0;
      const historyCodeUpdated = (historyCodeResult.rows[0] as any)?.rows_updated ?? 0;
      console.log(`Pass 2 (location-code match): rent_roll_data=${dataCodeUpdated}, rent_roll_history=${historyCodeUpdated}`);

      const postCheckResult = await db.execute(sql`
        SELECT
          (SELECT count(*)::int FROM rent_roll_data    WHERE location_id IS NULL AND location IS NOT NULL AND location != '') AS data_null_post,
          (SELECT count(*)::int FROM rent_roll_history WHERE location_id IS NULL AND location IS NOT NULL AND location != '') AS history_null_post
      `);
      const postCheck = postCheckResult.rows[0] as any;
      console.log(`Post-backfill nulls: rent_roll_data=${postCheck?.data_null_post}, rent_roll_history=${postCheck?.history_null_post}`);

      const totalDataUpdated = dataUpdated + dataCodeUpdated;
      const totalHistoryUpdated = historyUpdated + historyCodeUpdated;

      res.json({
        success: true,
        rentRollDataRowsUpdated: totalDataUpdated,
        rentRollHistoryRowsUpdated: totalHistoryUpdated,
        pass1: { rentRollDataRowsUpdated: dataUpdated, rentRollHistoryRowsUpdated: historyUpdated },
        pass2: { rentRollDataRowsUpdated: dataCodeUpdated, rentRollHistoryRowsUpdated: historyCodeUpdated },
        preCheckCounts: {
          rentRollDataNullBefore: preCheck?.data_null_pre ?? 0,
          rentRollHistoryNullBefore: preCheck?.history_null_pre ?? 0,
        },
        postCheckCounts: {
          rentRollDataNullAfter: postCheck?.data_null_post ?? 0,
          rentRollHistoryNullAfter: postCheck?.history_null_post ?? 0,
        },
        message: `Backfill complete. Updated ${totalDataUpdated} rent_roll_data rows and ${totalHistoryUpdated} rent_roll_history rows (pass1: ${dataUpdated}+${historyUpdated}, pass2: ${dataCodeUpdated}+${historyCodeUpdated}).`
      });
    } catch (error) {
      console.error('Error running location_id backfill:', error);
      res.status(500).json({ error: 'Failed to run location_id backfill' });
    }
  });

  // POST /api/admin/backfill-occupancy-history-location-ids
  // One-time backfill: matches room_type_occupancy_history rows that have a non-null
  // location_name but a null location_id against the locations table by (clientId, locationName)
  // and populates location_id. Safe to run repeatedly (idempotent).
  app.post('/api/admin/backfill-occupancy-history-location-ids', async (req: any, res) => {
    const session = req.session as any;
    if (!session?.userId || !session?.clientId) {
      return res.status(403).json({ error: 'Unauthorized: must be logged in as an admin' });
    }
    try {
      const userRows = await db.select().from(users).where(eq(users.id, session.userId)).limit(1);
      if (userRows.length === 0 || !userRows[0].username?.endsWith('_admin')) {
        return res.status(403).json({ error: 'Unauthorized: admin privileges required' });
      }
    } catch (e: any) {
      return res.status(500).json({ error: 'Failed to verify admin status' });
    }

    const clientId = session.clientId as string;

    try {
      console.log(`Running location_id backfill for room_type_occupancy_history (client: ${clientId})...`);

      const preCheckResult = await db.execute(sql`
        SELECT count(*)::int AS null_pre
        FROM room_type_occupancy_history
        WHERE client_id = ${clientId}
          AND location_id IS NULL
          AND location_name IS NOT NULL
          AND trim(location_name) != ''
      `);
      const nullBefore = (preCheckResult.rows[0] as any)?.null_pre ?? 0;
      console.log(`Pre-backfill nulls: ${nullBefore}`);

      const updateResult = await db.execute(sql`
        WITH updated AS (
          UPDATE room_type_occupancy_history roh
          SET location_id = loc.id
          FROM locations loc
          WHERE roh.client_id = ${clientId}
            AND roh.location_id IS NULL
            AND roh.location_name IS NOT NULL
            AND trim(roh.location_name) != ''
            AND lower(trim(roh.location_name)) = lower(trim(loc.name))
            AND loc.client_id = ${clientId}
          RETURNING roh.id
        )
        SELECT count(*)::int AS rows_updated FROM updated
      `);
      const rowsUpdated = (updateResult.rows[0] as any)?.rows_updated ?? 0;
      console.log(`Backfill updated ${rowsUpdated} room_type_occupancy_history rows.`);

      const postCheckResult = await db.execute(sql`
        SELECT count(*)::int AS null_post
        FROM room_type_occupancy_history
        WHERE client_id = ${clientId}
          AND location_id IS NULL
          AND location_name IS NOT NULL
          AND trim(location_name) != ''
      `);
      const nullAfter = (postCheckResult.rows[0] as any)?.null_post ?? 0;
      console.log(`Post-backfill nulls: ${nullAfter}`);

      res.json({
        success: true,
        rowsUpdated,
        nullLocationIdBefore: nullBefore,
        nullLocationIdAfter: nullAfter,
        message: `Backfill complete. Updated ${rowsUpdated} room_type_occupancy_history rows for client '${clientId}' (${nullBefore} had null locationId before, ${nullAfter} remain after).`,
      });
    } catch (error) {
      console.error('Error running occupancy history location_id backfill:', error);
      res.status(500).json({ error: 'Failed to run occupancy history location_id backfill' });
    }
  });

  // POST /api/admin/backfill-survey-coords
  // Backfill lat/lng on competitive_survey_data rows that either:
  //   (a) have coordinates already stored in the notes JSON (latitude/longitude fields), or
  //   (b) can be geocoded from the competitorAddress column via the geocoding service.
  // Rows that already have lat/lng populated are skipped (idempotent).
  app.post('/api/admin/backfill-survey-coords', async (req: any, res) => {
    const session = req.session as any;
    if (!session?.userId || !session?.clientId) {
      return res.status(403).json({ error: 'Unauthorized: must be logged in as an admin' });
    }
    try {
      const userRows = await db.select().from(users).where(eq(users.id, session.userId)).limit(1);
      if (userRows.length === 0 || !userRows[0].username?.endsWith('_admin')) {
        return res.status(403).json({ error: 'Unauthorized: admin privileges required' });
      }
    } catch (e: any) {
      return res.status(500).json({ error: 'Failed to verify admin status' });
    }

    const clientId = session.clientId as string;

    try {
      const { geocodeAddress } = await import('./geocoding');

      const rows = await db
        .select({
          id: competitiveSurveyData.id,
          notes: competitiveSurveyData.notes,
          competitorAddress: competitiveSurveyData.competitorAddress,
          lat: competitiveSurveyData.lat,
          lng: competitiveSurveyData.lng,
        })
        .from(competitiveSurveyData)
        .where(and(
          eq(competitiveSurveyData.clientId, clientId),
          or(isNull(competitiveSurveyData.lat), isNull(competitiveSurveyData.lng))
        ));

      let updated = 0;
      let failed = 0;

      for (const row of rows) {
        // Try to get coordinates from the notes JSON (imported from CSV Latitude/Longitude columns)
        let lat: number | null = null;
        let lng: number | null = null;
        try {
          const notes = typeof row.notes === 'string' ? JSON.parse(row.notes) : (row.notes || {});
          if (notes.latitude && notes.longitude) {
            lat = parseFloat(notes.latitude);
            lng = parseFloat(notes.longitude);
          }
        } catch {
          // notes not valid JSON, ignore
        }

        // Fall back to geocoding the address
        if ((lat == null || lng == null) && row.competitorAddress) {
          const coords = await geocodeAddress(row.competitorAddress);
          if (coords) {
            lat = coords.lat;
            lng = coords.lng;
          }
        }

        if (lat != null && lng != null) {
          await db
            .update(competitiveSurveyData)
            .set({ lat, lng })
            .where(and(eq(competitiveSurveyData.id, row.id), eq(competitiveSurveyData.clientId, clientId)));
          updated++;
        } else {
          failed++;
        }
      }

      res.json({
        message: 'Survey coordinate backfill complete',
        updated,
        failed,
        total: rows.length,
      });
    } catch (error: any) {
      console.error('Error running survey coords backfill:', error);
      res.status(500).json({ error: 'Failed to run survey coords backfill', details: error.message });
    }
  });

  // Cleanup orphaned location rows that have zero references across all FK-referencing tables.
  // Tenant-scoped to the authenticated admin's client — does NOT touch other tenants.
  // Requires a logged-in _admin user. Safe to run repeatedly (idempotent).
  app.post('/api/admin/cleanup-orphaned-locations', async (req: any, res) => {
    // Server-side admin gate: require a logged-in _admin user
    const session = req.session as any;
    if (!session?.userId || !session?.clientId) {
      return res.status(403).json({ error: 'Unauthorized: must be logged in as an admin' });
    }
    try {
      const userRows = await db.select().from(users).where(eq(users.id, session.userId)).limit(1);
      if (userRows.length === 0 || !userRows[0].username?.endsWith('_admin')) {
        return res.status(403).json({ error: 'Unauthorized: admin privileges required' });
      }
    } catch (e: any) {
      return res.status(500).json({ error: 'Failed to verify admin status' });
    }

    const clientId = session.clientId as string;

    try {
      console.log(`Scanning for orphaned location rows for client: ${clientId}`);

      // An orphaned alternate-name location is one that has ZERO references in ANY
      // table that FK-references locations. Checking all referencing tables ensures we
      // never delete a canonical location that simply hasn't had rent roll data imported
      // yet but is otherwise active (e.g. in competitors, floor plans, pricing tables).
      // Scoped to the authenticated admin's tenant to prevent cross-tenant deletion.
      const orphansResult = await db.execute(sql`
        SELECT loc.id, loc.name, loc.client_id, loc.location_code
        FROM locations loc
        WHERE loc.client_id = ${clientId}
          AND NOT EXISTS (SELECT 1 FROM rent_roll_data        WHERE location_id          = loc.id)
          AND NOT EXISTS (SELECT 1 FROM rent_roll_history     WHERE location_id          = loc.id)
          AND NOT EXISTS (SELECT 1 FROM competitors           WHERE location_id          = loc.id)
          AND NOT EXISTS (SELECT 1 FROM floor_plans           WHERE location_id          = loc.id)
          AND NOT EXISTS (SELECT 1 FROM guardrails            WHERE location_id          = loc.id)
          AND NOT EXISTS (SELECT 1 FROM pricing_weights       WHERE location_id          = loc.id)
          AND NOT EXISTS (SELECT 1 FROM rate_card             WHERE location_id          = loc.id)
          AND NOT EXISTS (SELECT 1 FROM targets_and_trends    WHERE location_id          = loc.id)
          AND NOT EXISTS (SELECT 1 FROM inquiry_metrics       WHERE location_id          = loc.id)
          AND NOT EXISTS (SELECT 1 FROM adjustment_ranges     WHERE location_id          = loc.id)
          AND NOT EXISTS (SELECT 1 FROM adjustment_rules      WHERE location_id          = loc.id)
          AND NOT EXISTS (SELECT 1 FROM campus_maps           WHERE location_id          = loc.id)
          AND NOT EXISTS (SELECT 1 FROM revenue_growth_targets WHERE location_id         = loc.id)
          AND NOT EXISTS (SELECT 1 FROM ai_rate_outcomes      WHERE location_id          = loc.id)
          AND NOT EXISTS (SELECT 1 FROM upload_history        WHERE location_id          = loc.id)
          AND NOT EXISTS (SELECT 1 FROM location_mappings     WHERE target_location_id   = loc.id)
          AND NOT EXISTS (SELECT 1 FROM enquire_data          WHERE mapped_location_id   = loc.id)
        ORDER BY loc.name
      `);

      const orphans = orphansResult.rows as { id: string; name: string; client_id: string | null; location_code: string | null }[];
      console.log(`Found ${orphans.length} orphaned location(s) for ${clientId}:`, orphans.map(o => o.name));

      if (orphans.length === 0) {
        return res.json({
          success: true,
          deletedCount: 0,
          deletedLocations: [],
          message: 'No orphaned location rows found. Nothing to clean up.',
        });
      }

      // Build tenant-scoped subquery that identifies orphaned location IDs
      const orphanSubquery = sql`
        SELECT loc_inner.id FROM locations loc_inner
        WHERE loc_inner.client_id = ${clientId}
          AND NOT EXISTS (SELECT 1 FROM rent_roll_data        WHERE location_id          = loc_inner.id)
          AND NOT EXISTS (SELECT 1 FROM rent_roll_history     WHERE location_id          = loc_inner.id)
          AND NOT EXISTS (SELECT 1 FROM competitors           WHERE location_id          = loc_inner.id)
          AND NOT EXISTS (SELECT 1 FROM floor_plans           WHERE location_id          = loc_inner.id)
          AND NOT EXISTS (SELECT 1 FROM guardrails            WHERE location_id          = loc_inner.id)
          AND NOT EXISTS (SELECT 1 FROM pricing_weights       WHERE location_id          = loc_inner.id)
          AND NOT EXISTS (SELECT 1 FROM rate_card             WHERE location_id          = loc_inner.id)
          AND NOT EXISTS (SELECT 1 FROM targets_and_trends    WHERE location_id          = loc_inner.id)
          AND NOT EXISTS (SELECT 1 FROM inquiry_metrics       WHERE location_id          = loc_inner.id)
          AND NOT EXISTS (SELECT 1 FROM adjustment_ranges     WHERE location_id          = loc_inner.id)
          AND NOT EXISTS (SELECT 1 FROM adjustment_rules      WHERE location_id          = loc_inner.id)
          AND NOT EXISTS (SELECT 1 FROM campus_maps           WHERE location_id          = loc_inner.id)
          AND NOT EXISTS (SELECT 1 FROM revenue_growth_targets WHERE location_id         = loc_inner.id)
          AND NOT EXISTS (SELECT 1 FROM ai_rate_outcomes      WHERE location_id          = loc_inner.id)
          AND NOT EXISTS (SELECT 1 FROM upload_history        WHERE location_id          = loc_inner.id)
          AND NOT EXISTS (SELECT 1 FROM location_mappings     WHERE target_location_id   = loc_inner.id)
          AND NOT EXISTS (SELECT 1 FROM enquire_data          WHERE mapped_location_id   = loc_inner.id)
      `;

      // Execute all deletes in a single transaction for atomicity.
      // For true orphans (no references anywhere) the dependent-table deletes are
      // no-ops by definition; they are included as a defensive belt-and-suspenders guard.
      await db.transaction(async (tx) => {
        await tx.execute(sql`DELETE FROM revenue_growth_targets WHERE location_id IN (${orphanSubquery})`);
        await tx.execute(sql`DELETE FROM adjustment_ranges     WHERE location_id IN (${orphanSubquery})`);
        await tx.execute(sql`DELETE FROM adjustment_rules      WHERE location_id IN (${orphanSubquery})`);
        await tx.execute(sql`DELETE FROM ai_rate_outcomes      WHERE location_id IN (${orphanSubquery})`);
        await tx.execute(sql`DELETE FROM campus_maps           WHERE location_id IN (${orphanSubquery})`);
        await tx.execute(sql`DELETE FROM competitors           WHERE location_id IN (${orphanSubquery})`);
        await tx.execute(sql`DELETE FROM enquire_data          WHERE mapped_location_id IN (${orphanSubquery})`);
        await tx.execute(sql`DELETE FROM floor_plans           WHERE location_id IN (${orphanSubquery})`);
        await tx.execute(sql`DELETE FROM guardrails            WHERE location_id IN (${orphanSubquery})`);
        await tx.execute(sql`DELETE FROM inquiry_metrics       WHERE location_id IN (${orphanSubquery})`);
        await tx.execute(sql`DELETE FROM location_mappings     WHERE target_location_id IN (${orphanSubquery})`);
        await tx.execute(sql`DELETE FROM pricing_weights       WHERE location_id IN (${orphanSubquery})`);
        await tx.execute(sql`DELETE FROM rate_card             WHERE location_id IN (${orphanSubquery})`);
        await tx.execute(sql`DELETE FROM targets_and_trends    WHERE location_id IN (${orphanSubquery})`);
        await tx.execute(sql`DELETE FROM upload_history        WHERE location_id IN (${orphanSubquery})`);

        // Delete the orphaned location rows (tenant-scoped)
        await tx.execute(sql`DELETE FROM locations WHERE id IN (${orphanSubquery})`);
      });

      console.log(`Deleted ${orphans.length} orphaned location(s).`);

      return res.json({
        success: true,
        deletedCount: orphans.length,
        deletedLocations: orphans.map(o => ({ id: o.id, name: o.name, clientId: o.client_id, locationCode: o.location_code })),
        message: `Cleanup complete. Removed ${orphans.length} orphaned location row(s).`,
      });
    } catch (error) {
      console.error('Error cleaning up orphaned locations:', error);
      res.status(500).json({ error: 'Failed to clean up orphaned locations' });
    }
  });

  // POST /api/admin/backfill-care-level-rates — harvest Level 2 care rates from rent_roll_history
  // and persist them into care_level_rates so the competitor formula has the correct "our" rate.
  // Only inserts rows that don't already have an admin-entered value (DO NOTHING on conflict).
  app.post('/api/admin/backfill-care-level-rates', async (req: any, res) => {
    // Require either a logged-in admin session OR the seed secret header (for automation)
    const seedSecret = req.headers['x-seed-secret'];
    const session = req.session as any;
    const hasSeedSecret = seedSecret && seedSecret === process.env.SEED_SECRET;
    if (!hasSeedSecret) {
      if (!session?.userId || !session?.clientId) {
        return res.status(403).json({ error: 'Unauthorized' });
      }
      try {
        const userRows = await db.select().from(users).where(eq(users.id, session.userId)).limit(1);
        if (userRows.length === 0 || !userRows[0].username?.endsWith('_admin')) {
          return res.status(403).json({ error: 'Unauthorized: admin privileges required' });
        }
      } catch {
        return res.status(500).json({ error: 'Failed to verify admin status' });
      }
    }

    const clientId = hasSeedSecret
      ? (req.body?.clientId || 'trilogy')
      : (session.clientId as string);

    try {
      console.log(`[backfill-care-level-rates] Starting backfill for client: ${clientId}`);
      const result = await storage.backfillCareLevelRatesFromHistory(clientId);
      console.log(`[backfill-care-level-rates] Done — upserted: ${result.upserted}, skipped: ${result.skipped}`);
      return res.json({
        success: true,
        upserted: result.upserted,
        skipped: result.skipped,
        message: `Backfill complete. Populated ${result.upserted} Level 2 care rate(s) from historical rent roll data. ${result.skipped} skipped (already set or no location match).`,
      });
    } catch (error: any) {
      console.error('[backfill-care-level-rates] Error:', error);
      return res.status(500).json({ error: 'Backfill failed', details: error.message });
    }
  });

