  // Guardrails CRUD
  app.get("/api/guardrails", async (req, res) => {
    try {
      const { locationId, serviceLine } = req.query;
      const cacheKey = `guardrails:${locationId || ''}:${serviceLine || ''}`;
      const cached = getCachedAnalytics(cacheKey);
      if (cached !== null) return res.json(cached);

      // 3-tier fallback: specific → location-only → global
      let guardrail;
      
      // Try location + serviceLine specific
      if (locationId && serviceLine) {
        [guardrail] = await db.select().from(guardrails)
          .where(and(
            eq(guardrails.locationId, locationId as string),
            eq(guardrails.serviceLine, serviceLine as string)
          ))
          .limit(1);
      }
      
      // Fall back to location-only (serviceLine=NULL)
      if (!guardrail && locationId) {
        [guardrail] = await db.select().from(guardrails)
          .where(and(
            eq(guardrails.locationId, locationId as string),
            sql`${guardrails.serviceLine} IS NULL`
          ))
          .limit(1);
      }
      
      // Fall back to global default (both NULL)
      if (!guardrail) {
        [guardrail] = await db.select().from(guardrails)
          .where(and(
            sql`${guardrails.locationId} IS NULL`,
            sql`${guardrails.serviceLine} IS NULL`
          ))
          .limit(1);
      }

      const result = guardrail || {};
      setCachedAnalytics(cacheKey, result);
      res.json(result);
    } catch (error) {
      console.error('Error fetching guardrails:', error);
      res.status(500).json({ error: "Failed to get guardrails" });
    }
  });

  const guardrailsBodySchema = z.object({
    locationId: z.string().nullable().optional(),
    serviceLine: z.string().nullable().optional(),
    minPriceChangePct: z.number().min(-100).max(0),
    maxPriceChangePct: z.number().min(0).max(500),
    minAbsolutePrice: z.number().positive().nullable().optional(),
    maxAbsolutePrice: z.number().positive().nullable().optional(),
  }).refine(d => d.minPriceChangePct <= d.maxPriceChangePct, {
    message: "minPriceChangePct cannot exceed maxPriceChangePct"
  }).refine(d => d.minAbsolutePrice == null || d.maxAbsolutePrice == null || d.minAbsolutePrice <= d.maxAbsolutePrice, {
    message: "minAbsolutePrice cannot exceed maxAbsolutePrice"
  });

  app.post("/api/guardrails", async (req, res) => {
    try {
      const parsed = guardrailsBodySchema.safeParse(req.body);
      if (!parsed.success) {
        return res.status(400).json({ error: parsed.error.errors[0]?.message || "Invalid guardrails data" });
      }
      const { locationId, serviceLine, ...guardrailData } = parsed.data;
      
      // Delete existing entry for this scope
      if (locationId && serviceLine) {
        await db.delete(guardrails).where(and(
          eq(guardrails.locationId, locationId),
          eq(guardrails.serviceLine, serviceLine)
        ));
      } else if (locationId) {
        await db.delete(guardrails).where(and(
          eq(guardrails.locationId, locationId),
          sql`${guardrails.serviceLine} IS NULL`
        ));
      } else {
        await db.delete(guardrails).where(and(
          sql`${guardrails.locationId} IS NULL`,
          sql`${guardrails.serviceLine} IS NULL`
        ));
      }
      
      // Insert new values (createdAt is auto-generated)
      const [newGuardrail] = await db.insert(guardrails).values({
        locationId: locationId || null,
        serviceLine: serviceLine || null,
        ...guardrailData
      }).returning();

      // Bust all guardrails cache entries that could be affected by this scope
      // (specific, location-only fallback, and global default).
      [`guardrails:${locationId || ''}:${serviceLine || ''}`,
       `guardrails:${locationId || ''}:`,
       'guardrails::'].forEach(k => setCachedAnalytics(k, null, 0));

      res.json({ ok: true, guardrails: newGuardrail });
    } catch (error) {
      console.error('Error saving guardrails:', error);
      res.status(400).json({ error: "Invalid guardrails data" });
    }
  });

