  // Analytics - Campus Metrics for Scatter Plots
  app.get("/api/analytics/campus-metrics", async (req: any, res) => {
    try {
      const { region, division, serviceLine } = req.query;
      const clientId = req.clientId || 'demo';
      
      // Check cache first
      const cacheKey = `campus-metrics:${clientId}:${region || 'all'}:${division || 'all'}:${serviceLine || 'all'}`;
      const cached = getCachedAnalytics(cacheKey);
      if (cached) {
        console.log(`Analytics: Serving cached result for ${cacheKey}`);
        return res.json(cached);
      }
      
      // Dynamically resolve the most recent month that has data for this client
      const mostRecentMonthRow = await db
        .select({ month: sql<string>`MAX(${rentRollData.uploadMonth})` })
        .from(rentRollData)
        .where(eq(rentRollData.clientId, clientId));
      const currentMonth = mostRecentMonthRow[0]?.month || (() => {
        const d = new Date();
        return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
      })();
      const [campusRentRoll, campusData, competitors, pricingWeights, surveyData] = await Promise.all([
        storage.getRentRollDataByMonth(currentMonth, clientId),  // Only get current month data
        storage.getAllCampuses(clientId),
        storage.getCompetitors(clientId),
        storage.getPricingWeights(),
        // Fetch competitive survey data as fallback for market position when units lack competitorFinalRate
        db.select({
          keyStatsLocation: competitiveSurveyData.keyStatsLocation,
          competitorType: competitiveSurveyData.competitorType,
          roomType: competitiveSurveyData.roomType,
          monthlyRateAvg: competitiveSurveyData.monthlyRateAvg,
        }).from(competitiveSurveyData).where(eq(competitiveSurveyData.clientId, clientId))
      ]);

      // Build a lookup map from competitive survey data:
      // location → compType → roomType → avg rate (for fallback market position)
      const surveyRateMap = new Map<string, Map<string, number[]>>();
      for (const row of surveyData) {
        if (!row.keyStatsLocation || !row.monthlyRateAvg || row.monthlyRateAvg <= 0) continue;
        if (!surveyRateMap.has(row.keyStatsLocation)) surveyRateMap.set(row.keyStatsLocation, new Map());
        const locMap = surveyRateMap.get(row.keyStatsLocation)!;
        const key = `${row.competitorType || 'ALL'}:${row.roomType || 'ALL'}`;
        if (!locMap.has(key)) locMap.set(key, []);
        locMap.get(key)!.push(row.monthlyRateAvg);
      }

      // Map service lines to competitor types for survey lookup
      const SL_TO_COMP_TYPE: Record<string, string> = {
        'HC': 'HC', 'HC/MC': 'SMC',
        'AL': 'AL', 'AL/MC': 'AL',
        'SL': 'IL_IL', 'VIL': 'IL_Villa',
      };
      
      console.log(`Analytics: Processing ${campusRentRoll.length} units for ${currentMonth}`);

      // Create a map of campus data for O(1) lookups instead of O(n) searches
      const campusDataMap = new Map();
      campusData.forEach((campus: any) => {
        campusDataMap.set(campus.name, campus);
      });

      // Filter rent roll data by service line first if needed
      let filteredRentRollData = campusRentRoll;
      if (serviceLine && serviceLine !== 'all') {
        filteredRentRollData = campusRentRoll.filter((unit: any) => unit.serviceLine === serviceLine);
      }

      // Group rent roll data by campus
      const campusMetrics = new Map();
      let debugTotalUnits = 0;
      let debugFilteredUnits = 0;
      let debugBBedsSkipped = 0;
      
      filteredRentRollData.forEach((unit: any) => {
        const campusId = unit.location || 'Unknown';
        debugTotalUnits++;
        
        // Filter out B-beds for senior housing service lines (AL, MC, IL)
        // Only count A-beds (room numbers NOT ending with /B)
        // Note: Drizzle ORM camelCases the field names
        const roomNum = unit.roomNumber || unit.room_number || '';
        const isABed = !roomNum || !roomNum.endsWith('/B');
        const isHC = unit.serviceLine === 'HC';
        
        // Skip B-beds for non-HC service lines
        if (!isHC && !isABed) {
          debugBBedsSkipped++;
          return; // Skip this unit
        }
        debugFilteredUnits++;
        
        if (!campusMetrics.has(campusId)) {
          campusMetrics.set(campusId, {
            campusId,
            campusName: campusId,
            units: [],
            totalUnits: 0,
            occupiedUnits: 0,
            totalRent: 0,
            vacantUnits: 0,
            avgLOS: 0,
            region: 'Unknown'
          });
        }
        
        const campus = campusMetrics.get(campusId);
        campus.units.push(unit);
        campus.totalUnits++;
        if (unit.occupiedYN) {
          campus.occupiedUnits++;
          // Use streetRate consistently for calculations, fallback to inHouseRate
          const rate = unit.streetRate || unit.inHouseRate || 0;
          campus.totalRent += rate;
        } else {
          campus.vacantUnits++;
        }
      });
      
      console.log(`Analytics Debug: Total=${debugTotalUnits}, Filtered=${debugFilteredUnits}, B-beds skipped=${debugBBedsSkipped}`);
      console.log(`Analytics Debug: Found ${campusMetrics.size} unique campuses`);

      // Override campus-level occupancy with room_type_occupancy_history (physical rooms, no B-bed inflation)
      {
        const [cmHistYr, cmHistMo] = currentMonth.split('-').map(Number);
        const cmHistRes = await pool.query(`
          SELECT location_name,
                 SUM(available_units)::float AS avail,
                 SUM(occ_units)::float        AS occ
          FROM room_type_occupancy_history
          WHERE client_id = $1 AND year = $2 AND month = $3
          GROUP BY location_name
        `, [clientId, cmHistYr, cmHistMo]);
        for (const r of cmHistRes.rows) {
          const m = campusMetrics.get(r.location_name);
          if (m && Number(r.avail) > 0) {
            m.totalUnits    = Math.round(Number(r.avail));
            m.occupiedUnits = Math.round(Number(r.occ));
            m.vacantUnits   = Math.max(0, m.totalUnits - m.occupiedUnits);
          }
        }
      }

      // Calculate portfolio-wide medians by room type as fallback when competitor data is missing
      const portfolioMediansByRoomType = new Map<string, number>();
      const ratesByRoomType = new Map<string, number[]>();
      
      campusRentRoll.forEach((unit: any) => {
        let roomType = unit.roomType || 'Unknown';
        // Normalize to competitor format
        if (roomType === 'One Bedroom') roomType = '1BR';
        else if (roomType === 'Two Bedroom') roomType = '2BR';
        
        const rate = unit.inHouseRate || unit.streetRate || 0;
        if (rate > 0) {
          if (!ratesByRoomType.has(roomType)) {
            ratesByRoomType.set(roomType, []);
          }
          ratesByRoomType.get(roomType)!.push(rate);
        }
      });
      
      // Calculate medians
      ratesByRoomType.forEach((rates, roomType) => {
        rates.sort((a, b) => a - b);
        const mid = Math.floor(rates.length / 2);
        const median = rates.length % 2 === 0
          ? (rates[mid - 1] + rates[mid]) / 2
          : rates[mid];
        portfolioMediansByRoomType.set(roomType, median);
      });
      
      // Group competitors by campus and room type for apples-to-apples comparison
      const competitorsByLocationAndType = new Map<string, Map<string, number[]>>();
      
      competitors.forEach((comp: any) => {
        const campusId = comp.location || 'Unknown';
        const roomType = comp.roomType || 'Unknown';
        
        if (!competitorsByLocationAndType.has(campusId)) {
          competitorsByLocationAndType.set(campusId, new Map());
        }
        
        const locationMap = competitorsByLocationAndType.get(campusId)!;
        if (!locationMap.has(roomType)) {
          locationMap.set(roomType, []);
        }
        
        // Filter out unrealistically low rates (likely data import errors)
        // Senior living monthly rates below $1000 are clearly errors (daily rates imported as monthly)
        const MIN_REALISTIC_MONTHLY_RATE = 1000;
        if (comp.streetRate && comp.streetRate > MIN_REALISTIC_MONTHLY_RATE) {
          locationMap.get(roomType)!.push(comp.streetRate);
        }
      });

      // Calculate metrics for each campus
      const campusesData: any[] = [];
      
      campusMetrics.forEach((metrics, campusId) => {
        const occupancy = metrics.occupiedUnits / metrics.totalUnits;
        const avgRate = metrics.occupiedUnits > 0 ? metrics.totalRent / metrics.occupiedUnits : 0;
        
        // Calculate rates by service line type for meaningful display
        let hcUnits = 0;
        let hcRate = 0;
        let seniorHousingUnits = 0;
        let seniorHousingRate = 0;
        
        metrics.units.forEach((unit: any) => {
          const rate = unit.streetRate || unit.inHouseRate || 0;
          if (unit.serviceLine === 'HC' || unit.serviceLine === 'HC/MC') {
            // HC rates are daily
            if (rate > 0) {
              hcRate += rate;
              hcUnits++;
            }
          } else {
            // Senior Housing rates are monthly (AL, IL, MC, SL, VIL)
            if (rate > 0) {
              seniorHousingRate += rate;
              seniorHousingUnits++;
            }
          }
        });
        
        // Calculate average rates by type
        const avgHcDailyRate = hcUnits > 0 ? hcRate / hcUnits : 0;
        const avgSeniorHousingMonthlyRate = seniorHousingUnits > 0 ? seniorHousingRate / seniorHousingUnits : 0;
        
        // DECISION (kept intentionally): market position here is benchmarked against
        // the TOP (highest) competitor adjusted rate from the competitive data — NOT
        // the average competitor rate, and NOT the shared care-adjusted market
        // benchmark (server/services/compBenchmark.ts) used by the Competitive
        // Position scatter and AI rule suggestions. Comparing against a blended
        // average overstated our premium (e.g. a campus could show +94% vs a low
        // blended average). The top comp is the most relevant pricing ceiling for
        // this campus-level view, and the UI labels it explicitly as "vs top
        // competitor" so it cannot be confused with the shared market benchmark.
        // If an AVERAGE-based premium is ever added here, it must come from
        // loadCompBenchmark/unitWeightedBenchmark — never a raw
        // competitor_final_rate average.
        //
        // Rates have two incompatible bases: HC / HC/MC are daily; senior housing
        // (AL, AL/MC, SL, VIL, IL) is monthly. We compute top comp + avg in-house rate
        // PER BASIS so daily and monthly rates are never mixed, then combine into a
        // single unit-weighted position. Outlier guards drop bad imports (negative
        // rates, daily rates parsed as monthly, the occasional six-figure VIL error).
        const DAILY_SERVICE_LINES = new Set(['HC', 'HC/MC', 'SMC']);
        const isValidCompRate = (rate: number, daily: boolean): boolean =>
          daily ? (rate >= 50 && rate <= 2000) : (rate >= 1000 && rate <= 50000);

        const basisAcc: Record<'daily' | 'monthly', { trilogySum: number; count: number; topComp: number }> = {
          daily: { trilogySum: 0, count: 0, topComp: 0 },
          monthly: { trilogySum: 0, count: 0, topComp: 0 },
        };

        metrics.units.forEach((unit: any) => {
          const comp = unit.competitorFinalRate || 0;
          if (comp <= 0) return;
          const daily = DAILY_SERVICE_LINES.has(unit.serviceLine);
          if (!isValidCompRate(comp, daily)) return;
          const trilogyRate = unit.streetRate || unit.inHouseRate || 0;
          if (trilogyRate <= 0) return;
          const b = daily ? basisAcc.daily : basisAcc.monthly;
          b.trilogySum += trilogyRate;
          b.count++;
          if (comp > b.topComp) b.topComp = comp;
        });

        let unitsWithCompetitorData = basisAcc.daily.count + basisAcc.monthly.count;

        // Fallback: if no units have competitorFinalRate, use competitive_survey_data.
        // Take the TOP (max) survey rate per room type, still bucketed by rate basis.
        if (unitsWithCompetitorData === 0) {
          const locSurveyMap = surveyRateMap.get(campusId);
          if (locSurveyMap) {
            metrics.units.forEach((unit: any) => {
              const trilogyRate = unit.streetRate || unit.inHouseRate || 0;
              if (trilogyRate <= 0) return;
              const compType = SL_TO_COMP_TYPE[unit.serviceLine] || null;
              if (!compType) return;
              // Normalize room type to match survey keys
              const rt = (unit.size || unit.roomType || '').replace('Two Bedroom', 'Two Bedroom').replace('One Bedroom', 'One Bedroom');
              const key = `${compType}:${rt}`;
              const fallbackKey = `${compType}:ALL`;
              const rates = locSurveyMap.get(key) || locSurveyMap.get(fallbackKey);
              if (rates && rates.length > 0) {
                const daily = DAILY_SERVICE_LINES.has(unit.serviceLine);
                const validRates = rates.filter((r: number) => isValidCompRate(r, daily));
                if (validRates.length === 0) return;
                const top = Math.max(...validRates);
                const b = daily ? basisAcc.daily : basisAcc.monthly;
                b.trilogySum += trilogyRate;
                b.count++;
                if (top > b.topComp) b.topComp = top;
              }
            });
            unitsWithCompetitorData = basisAcc.daily.count + basisAcc.monthly.count;
          }
        }

        // Price position vs the top competitor, computed per basis then unit-weighted.
        let pricePosition = 0;
        let weightedPos = 0;
        let weightTotal = 0;
        (['daily', 'monthly'] as const).forEach((key) => {
          const b = basisAcc[key];
          if (b.count > 0 && b.topComp > 0) {
            const avgTril = b.trilogySum / b.count;
            const pos = ((avgTril - b.topComp) / b.topComp) * 100;
            weightedPos += pos * b.count;
            weightTotal += b.count;
          }
        });
        if (weightTotal > 0) pricePosition = weightedPos / weightTotal;

        // Representative top comp + in-house rate for tooltips/exports follow the
        // campus's PRIMARY rate basis (whichever basis most of its units belong to),
        // so the single displayed "Top Comp Rate" lines up with the rate shown for the
        // campus (e.g. a senior-housing campus shows the monthly top comp, not a daily
        // HC one). The weighted pricePosition above still accounts for both bases.
        let dailyUnitCount = 0;
        let monthlyUnitCount = 0;
        metrics.units.forEach((unit: any) => {
          if (DAILY_SERVICE_LINES.has(unit.serviceLine)) dailyUnitCount++;
          else monthlyUnitCount++;
        });
        const primaryIsDaily = dailyUnitCount > monthlyUnitCount;
        let dominantBasis = primaryIsDaily ? basisAcc.daily : basisAcc.monthly;
        // Fall back to the other basis if the primary one has no competitor data.
        if (dominantBasis.count === 0) {
          dominantBasis = primaryIsDaily ? basisAcc.monthly : basisAcc.daily;
        }
        const avgCompetitorRate = dominantBasis.topComp;
        const avgTrilogyRateWithComp = dominantBasis.count > 0 ? dominantBasis.trilogySum / dominantBasis.count : 0;
          
        // Calculate revenue impact (simplified)
        const currentMonthlyRevenue = avgRate * metrics.occupiedUnits * 30;
        const potentialRevenue = avgRate * metrics.totalUnits * 30 * 0.95; // Assume 95% max occupancy
        const revenueImpact = potentialRevenue - currentMonthlyRevenue;

        // Find campus info for region and division (name field is the KeyStats name)
        const campusInfo = campusDataMap.get(campusId);
        const campusRegion = campusInfo?.region || 'Unknown';
        const campusDivision = campusInfo?.division || 'Unknown';
        
        // Apply filters
        if (region && region !== 'all' && campusRegion !== region) {
          return;
        }
        
        if (division && division !== 'all' && campusDivision !== division) {
          return;
        }

        // Determine primary service line for this campus
        const serviceLineCounts = metrics.units.reduce((acc: any, u: any) => {
          const sl = u.serviceLine || 'Unknown';
          acc[sl] = (acc[sl] || 0) + 1;
          return acc;
        }, {});
        const primaryServiceLine = Object.entries(serviceLineCounts)
          .sort((a: any, b: any) => b[1] - a[1])[0]?.[0] || 'All';

        campusesData.push({
          campusId,
          campusName: campusInfo?.name || campusId,
          region: campusRegion,
          division: campusDivision,
          serviceLine: primaryServiceLine,
          avgRate: Math.round(avgRate),
          avgHcDailyRate: Math.round(avgHcDailyRate), // HC daily rate
          avgSeniorHousingMonthlyRate: Math.round(avgSeniorHousingMonthlyRate), // Senior Housing monthly rate
          hcUnits,
          seniorHousingUnits,
          occupancy,
          occupiedUnits: metrics.occupiedUnits,  // Add occupied units for weighted avg
          competitorAvgRate: Math.round(avgCompetitorRate), // Use adjusted competitor rate
          pricePosition,
          revenueImpact,
          potentialRevenue,
          unitsCount: metrics.totalUnits,
          vacantUnits: metrics.vacantUnits,
          avgLOS: 0, // Would calculate from actual data
          marketShareScore: occupancy * 100
        });
      });

      // Calculate portfolio summary with proper weighted averages
      const totalOccupiedUnits = campusesData.reduce((sum, c) => sum + (c.occupiedUnits || 0), 0);
      const totalRentRevenue = campusesData.reduce((sum, c) => 
        sum + (c.avgRate * (c.occupiedUnits || 0)), 0);
      const totalUnits = campusesData.reduce((sum, c) => sum + c.unitsCount, 0);
      
      // Calculate weighted average price position (by number of units with competitor data)
      let totalWeightedPosition = 0;
      let totalUnitsWithData = 0;
      campusesData.forEach(campus => {
        // Only include campuses with actual competitor data in the average
        if (campus.pricePosition !== 0 && campus.competitorAvgRate > 0) {
          totalWeightedPosition += campus.pricePosition * campus.unitsCount;
          totalUnitsWithData += campus.unitsCount;
        }
      });
      
      // Calculate average rates by service line type for portfolio summary
      const totalHcUnits = campusesData.reduce((sum, c) => sum + (c.hcUnits || 0), 0);
      const totalSeniorHousingUnits = campusesData.reduce((sum, c) => sum + (c.seniorHousingUnits || 0), 0);
      
      const avgHcDailyRate = totalHcUnits > 0 ?
        campusesData.reduce((sum, c) => sum + (c.avgHcDailyRate * (c.hcUnits || 0)), 0) / totalHcUnits : 0;
      
      const avgSeniorHousingMonthlyRate = totalSeniorHousingUnits > 0 ?
        campusesData.reduce((sum, c) => sum + (c.avgSeniorHousingMonthlyRate * (c.seniorHousingUnits || 0)), 0) / totalSeniorHousingUnits : 0;
      
      const summary = {
        avgPortfolioRate: totalOccupiedUnits > 0 
          ? Math.round(totalRentRevenue / totalOccupiedUnits)
          : 0,
        avgHcDailyRate: Math.round(avgHcDailyRate),  // HC daily rate average
        avgSeniorHousingMonthlyRate: Math.round(avgSeniorHousingMonthlyRate),  // Senior Housing monthly rate average
        avgOccupancy: totalUnits > 0
          ? campusesData.reduce((sum, c) => sum + (c.occupiedUnits || 0), 0) / totalUnits
          : 0,
        avgPricePosition: totalUnitsWithData > 0
          ? totalWeightedPosition / totalUnitsWithData
          : 0,
        totalRevenueOpportunity: campusesData.reduce((sum, c) => sum + c.revenueImpact, 0),
        totalOccupiedUnits,  // Add for dialog display
        totalRentRevenue: Math.round(totalRentRevenue * 30),  // Monthly revenue
        campusesWithCompetitorData: campusesData.filter(c => c.pricePosition !== 0).length
      };

      const result = {
        campuses: campusesData,
        summary
      };
      
      // Cache the result for 5 minutes
      setCachedAnalytics(cacheKey, result);
      
      res.json(result);
    } catch (error) {
      console.error("Error fetching analytics data:", error);
      res.status(500).json({ error: "Failed to fetch analytics data" });
    }
  });

  // Vacancy scatter plot data endpoint
  app.get("/api/analytics/vacancy-scatter", async (req: any, res) => {
    try {
      const { location, serviceLine } = req.query;
      const clientId = req.clientId || 'demo';
      
      // Check cache first
      const cacheKey = `vacancy-scatter:${clientId}:${location || 'all'}:${serviceLine || 'all'}`;
      const cached = getCachedAnalytics(cacheKey);
      if (cached) {
        console.log(`Vacancy: Serving cached result for ${cacheKey}`);
        return res.json(cached);
      }
      
      // Get the most recent month's data from the database (filtered by clientId)
      const mostRecentMonthResult = await db
        .select({ month: sql<string>`MAX(${rentRollData.uploadMonth})` })
        .from(rentRollData)
        .where(eq(rentRollData.clientId, clientId));
      const uploadMonth = mostRecentMonthResult[0]?.month || '2025-11';
      
      console.log('Vacancy analysis using upload month:', uploadMonth);
      
      // Get all rent roll data - getRentRollDataFiltered expects month as first param, filters as second
      const filters: any = { clientId };
      if (location) {
        filters.locations = [location as string];
      }
      // Note: getRentRollDataFiltered doesn't support serviceLine filter directly
      // We'll filter by serviceLine in memory after fetching
      let allRentRollData = await storage.getRentRollDataFiltered(uploadMonth, filters);
      
      // Filter by service line if provided
      if (serviceLine) {
        allRentRollData = allRentRollData.filter(unit => unit.serviceLine === serviceLine);
      }
      
      // Calculate campus occupancy by location
      const campusMetrics = new Map<string, { occupied: number; total: number; occupancy: number }>();
      
      allRentRollData.forEach(unit => {
        const campus = unit.location;
        if (!campusMetrics.has(campus)) {
          campusMetrics.set(campus, { occupied: 0, total: 0, occupancy: 0 });
        }
        const metrics = campusMetrics.get(campus)!;
        
        // For senior housing, count units (A-beds only), for HC count all beds
        const isHC = unit.serviceLine === 'HC' || unit.serviceLine === 'HC/MC';
        const isBBed = unit.roomNumber?.toString().toUpperCase().endsWith('B');
        
        if (isHC || !isBBed) {  // Count all HC beds, but only A-beds for senior housing
          metrics.total++;
          if (unit.occupiedYN) {
            metrics.occupied++;
          }
        }
      });
      
      // Calculate occupancy for each campus
      campusMetrics.forEach((metrics, campus) => {
        metrics.occupancy = metrics.total > 0 ? (metrics.occupied / metrics.total) : 0;
      });
      
      // Get vacant units and B-beds
      const vacancyData: any[] = [];
      
      allRentRollData.forEach(unit => {
        const isHC = unit.serviceLine === 'HC' || unit.serviceLine === 'HC/MC';
        const isBBed = unit.roomNumber?.toString().toUpperCase().endsWith('B');
        
        // Include if:
        // 1. Unit is vacant (not occupied)
        // 2. OR it's a B-bed in HC (always show B-beds)
        if (!unit.occupiedYN || (isHC && isBBed)) {
          const campusOccupancy = campusMetrics.get(unit.location)?.occupancy || 0;
          
          vacancyData.push({
            id: `${unit.location}-${unit.roomNumber}`,
            location: unit.location,
            serviceLine: unit.serviceLine,
            roomNumber: unit.roomNumber,
            roomType: unit.roomType,
            daysVacant: unit.daysVacant || 0,
            campusOccupancy: campusOccupancy * 100, // Convert to percentage
            streetRate: unit.streetRate || 0,
            isBBed,
            isVacant: !unit.occupiedYN,
            unitType: isBBed ? 'B-Bed' : 'A-Bed'
          });
        }
      });
      
      // Sort by days vacant descending for better visualization
      vacancyData.sort((a, b) => b.daysVacant - a.daysVacant);
      
      const result = {
        units: vacancyData,
        summary: {
          totalVacantUnits: vacancyData.filter(u => u.isVacant && !u.isBBed).length,
          totalBBeds: vacancyData.filter(u => u.isBBed).length,
          avgDaysVacant: vacancyData.length > 0 
            ? vacancyData.reduce((sum, u) => sum + u.daysVacant, 0) / vacancyData.length 
            : 0,
          maxDaysVacant: Math.max(...vacancyData.map(u => u.daysVacant), 0)
        }
      };
      
      // Cache the result for 5 minutes
      setCachedAnalytics(cacheKey, result);
      
      res.json(result);
    } catch (error) {
      console.error("Error fetching vacancy scatter data:", error);
      res.status(500).json({ error: "Failed to fetch vacancy scatter data" });
    }
  });

  // Rate breakdown analytics - rates by service line and room type with historical changes
  app.get("/api/analytics/rate-breakdown", async (req: any, res) => {
    try {
      const clientId = req.clientId || 'demo';
      // Get all available months from the database
      const monthsResult = await db
        .select({ month: sql<string>`DISTINCT ${rentRollData.uploadMonth}` })
        .from(rentRollData)
        .where(eq(rentRollData.clientId, clientId))
        .orderBy(sql`${rentRollData.uploadMonth} DESC`);
      
      const availableMonths = monthsResult.map(m => m.month).filter(Boolean).sort().reverse();
      console.log('Rate breakdown: Available months:', availableMonths);
      
      if (availableMonths.length === 0) {
        return res.json({ 
          byServiceLine: [], 
          byServiceLineRoomType: [],
          currentMonth: null 
        });
      }
      
      const currentMonth = availableMonths[0];
      
      // Calculate date references
      const currentDate = new Date(currentMonth + '-01');
      const getMonthStr = (date: Date) => {
        return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}`;
      };
      
      // Previous periods
      const previousMonth = new Date(currentDate);
      previousMonth.setMonth(previousMonth.getMonth() - 1);
      const previousMonthStr = getMonthStr(previousMonth);
      
      const t3Month = new Date(currentDate);
      t3Month.setMonth(t3Month.getMonth() - 3);
      const t3MonthStr = getMonthStr(t3Month);
      
      const t6Month = new Date(currentDate);
      t6Month.setMonth(t6Month.getMonth() - 6);
      const t6MonthStr = getMonthStr(t6Month);
      
      const t12Month = new Date(currentDate);
      t12Month.setMonth(t12Month.getMonth() - 12);
      const t12MonthStr = getMonthStr(t12Month);
      
      // YTD - first month of current year
      const ytdMonth = `${currentDate.getFullYear()}-01`;
      
      // Get data for all needed months (only fetch months that exist)
      const monthsToFetch = [currentMonth, previousMonthStr, t3MonthStr, t6MonthStr, t12MonthStr, ytdMonth]
        .filter((m, i, arr) => arr.indexOf(m) === i && availableMonths.includes(m));
      
      console.log('Rate breakdown: Fetching months:', monthsToFetch);
      
      const allData: any[] = [];
      for (const month of monthsToFetch) {
        const monthData = await storage.getRentRollDataByMonth(month, clientId);
        allData.push(...monthData.map((u: any) => ({ ...u, fetchedMonth: month })));
      }
      
      // Helper to calculate average rate for a filter
      const calcAvgRate = (units: any[]) => {
        // Use inHouseRate for occupied, streetRate for all
        const occupiedUnits = units.filter(u => u.occupiedYN === true || u.occupiedYN === 'Y');
        if (occupiedUnits.length === 0) return null;
        
        let totalRate = 0;
        let count = 0;
        
        for (const unit of occupiedUnits) {
          // Normalize to monthly rate for comparison
          const serviceLine = unit.serviceLine || '';
          const isDaily = serviceLine === 'HC' || serviceLine === 'HC/MC';
          const rate = unit.inHouseRate || unit.streetRate || 0;
          const monthlyRate = isDaily ? rate * 30.44 : rate;
          
          if (monthlyRate > 0) {
            totalRate += monthlyRate;
            count++;
          }
        }
        
        return count > 0 ? Math.round(totalRate / count) : null;
      };
      
      // Calculate % change helper
      const calcChange = (current: number | null, previous: number | null): number | null => {
        if (current === null || previous === null || previous === 0) return null;
        return Math.round(((current - previous) / previous) * 1000) / 10; // 1 decimal place
      };
      
      // Get current month data
      const currentData = allData.filter(u => u.uploadMonth === currentMonth);
      
      // Get unique service lines and room types
      const serviceLines = [...new Set(currentData.map(u => u.serviceLine))].filter(Boolean).sort();
      const roomTypes = [...new Set(currentData.map(u => u.roomType))].filter(Boolean).sort();
      
      // Calculate rates by service line
      const byServiceLine = serviceLines.map(sl => {
        const currentUnits = currentData.filter(u => u.serviceLine === sl);
        const prevUnits = allData.filter(u => u.uploadMonth === previousMonthStr && u.serviceLine === sl);
        const t3Units = allData.filter(u => u.uploadMonth === t3MonthStr && u.serviceLine === sl);
        const t6Units = allData.filter(u => u.uploadMonth === t6MonthStr && u.serviceLine === sl);
        const t12Units = allData.filter(u => u.uploadMonth === t12MonthStr && u.serviceLine === sl);
        const ytdUnits = allData.filter(u => u.uploadMonth === ytdMonth && u.serviceLine === sl);
        
        const currentRate = calcAvgRate(currentUnits);
        const prevRate = calcAvgRate(prevUnits);
        const t3Rate = calcAvgRate(t3Units);
        const t6Rate = calcAvgRate(t6Units);
        const t12Rate = calcAvgRate(t12Units);
        const ytdRate = calcAvgRate(ytdUnits);
        
        // Determine if this service line uses daily rates
        const isDaily = sl === 'HC' || sl === 'HC/MC';
        
        return {
          serviceLine: sl,
          currentRate,
          isDaily,
          rateDisplay: currentRate ? (isDaily ? `$${Math.round(currentRate / 30.44)}/day` : `$${currentRate.toLocaleString()}/mo`) : 'N/A',
          unitCount: currentUnits.length,
          occupiedCount: currentUnits.filter(u => u.occupiedYN === true || u.occupiedYN === 'Y').length,
          momChange: calcChange(currentRate, prevRate),
          t3Change: calcChange(currentRate, t3Rate),
          t6Change: calcChange(currentRate, t6Rate),
          t12Change: calcChange(currentRate, t12Rate),
          ytdChange: calcChange(currentRate, ytdRate),
        };
      });
      
      // Calculate rates by service line + room type (limit to top combinations)
      const byServiceLineRoomType: any[] = [];
      
      for (const sl of serviceLines) {
        for (const rt of roomTypes) {
          const currentUnits = currentData.filter(u => u.serviceLine === sl && u.roomType === rt);
          if (currentUnits.length < 3) continue; // Skip combinations with very few units
          
          const prevUnits = allData.filter(u => u.uploadMonth === previousMonthStr && u.serviceLine === sl && u.roomType === rt);
          const t3Units = allData.filter(u => u.uploadMonth === t3MonthStr && u.serviceLine === sl && u.roomType === rt);
          const t6Units = allData.filter(u => u.uploadMonth === t6MonthStr && u.serviceLine === sl && u.roomType === rt);
          const t12Units = allData.filter(u => u.uploadMonth === t12MonthStr && u.serviceLine === sl && u.roomType === rt);
          const ytdUnits = allData.filter(u => u.uploadMonth === ytdMonth && u.serviceLine === sl && u.roomType === rt);
          
          const currentRate = calcAvgRate(currentUnits);
          const prevRate = calcAvgRate(prevUnits);
          const t3Rate = calcAvgRate(t3Units);
          const t6Rate = calcAvgRate(t6Units);
          const t12Rate = calcAvgRate(t12Units);
          const ytdRate = calcAvgRate(ytdUnits);
          
          const isDaily = sl === 'HC' || sl === 'HC/MC';
          
          byServiceLineRoomType.push({
            serviceLine: sl,
            roomType: rt,
            currentRate,
            isDaily,
            rateDisplay: currentRate ? (isDaily ? `$${Math.round(currentRate / 30.44)}/day` : `$${currentRate.toLocaleString()}/mo`) : 'N/A',
            unitCount: currentUnits.length,
            occupiedCount: currentUnits.filter(u => u.occupiedYN === true || u.occupiedYN === 'Y').length,
            momChange: calcChange(currentRate, prevRate),
            t3Change: calcChange(currentRate, t3Rate),
            t6Change: calcChange(currentRate, t6Rate),
            t12Change: calcChange(currentRate, t12Rate),
            ytdChange: calcChange(currentRate, ytdRate),
          });
        }
      }
      
      // Sort by unit count descending
      byServiceLineRoomType.sort((a, b) => b.unitCount - a.unitCount);
      
      res.json({
        byServiceLine,
        byServiceLineRoomType: byServiceLineRoomType.slice(0, 30), // Limit to top 30 combinations
        currentMonth,
        availableMonths: monthsToFetch,
      });
    } catch (error) {
      console.error("Error fetching rate breakdown data:", error);
      res.status(500).json({ error: "Failed to fetch rate breakdown data" });
    }
  });

  // AI Insights
  app.post("/api/ai/suggest", async (req: any, res) => {
    try {
      const clientId = req.clientId || 'demo';
      const { location, serviceLine } = req.body || {};

      // Latest month
      const latestMonthResult = await db
        .select({ uploadMonth: rentRollData.uploadMonth })
        .from(rentRollData)
        .where(and(sql`${rentRollData.uploadMonth} IS NOT NULL`, eq(rentRollData.clientId, clientId)))
        .orderBy(sql`${rentRollData.uploadMonth} DESC`)
        .limit(1);
      const latestMonth = latestMonthResult[0]?.uploadMonth || '2026-05';

      let allRentRollData = await storage.getRentRollDataByMonth(latestMonth, clientId);
      let allCompetitors = await storage.getCompetitors(clientId);

      // Apply filters
      let filteredData = allRentRollData;
      let filteredCompetitors = allCompetitors;
      if (location) {
        filteredData = filteredData.filter(u => u.location === location);
        filteredCompetitors = filteredCompetitors.filter(c => c.location === location);
      }
      if (serviceLine) {
        filteredData = filteredData.filter(u => u.serviceLine === serviceLine);
      }

      if (filteredData.length === 0) {
        return res.status(400).json({ error: 'No units found for the selected filters.' });
      }

      // ── Resolve location ID for weight/target lookups ──────────────────────
      const locationId = filteredData[0]?.locationId || null;

      // ── Pricing weights: 3-tier fallback (location+SL → location → global) ──
      let weights = locationId && serviceLine
        ? await storage.getWeightsByFilter(locationId, serviceLine)
        : undefined;
      if (!weights && locationId) weights = await storage.getWeightsByFilter(locationId, null);
      if (!weights) weights = await storage.getWeightsByFilter(undefined, undefined);

      // ── Revenue growth targets for this location ───────────────────────────
      const revenueTargets = locationId
        ? await storage.getRevenueGrowthTargets(locationId)
        : [];

      // ── Basic occupancy / rate stats ───────────────────────────────────────
      const totalUnits = filteredData.length;
      const longVacant = filteredData.filter(u => !u.occupiedYN && (u.daysVacant || 0) > 30).length;

      // ── Authoritative occupancy: room_type_occupancy_history overrides occupied_yn ──
      const aiSuggestMY = latestMonth
        ? { year: parseInt(latestMonth.slice(0, 4)), month: parseInt(latestMonth.slice(5, 7)) }
        : null;
      let rtoOcc = 0, rtoAvail = 0;
      if (aiSuggestMY) {
        const rtoP: any[] = [clientId, aiSuggestMY.year, aiSuggestMY.month];
        const rtoLocW = location ? ` AND location_name = $${rtoP.push(location)}` : '';
        const rtoRes = await pool.query(
          `SELECT service_line, SUM(occ_units) AS occ, SUM(available_units) AS avail
           FROM room_type_occupancy_history
           WHERE client_id=$1 AND year=$2 AND month=$3${rtoLocW}
           GROUP BY service_line`,
          rtoP
        );
        for (const r of rtoRes.rows) {
          const toks = String(r.service_line || '').split(',').map((t: string) => t.trim());
          if (!serviceLine || toks.includes(serviceLine)) {
            rtoOcc   += parseFloat(r.occ   || '0');
            rtoAvail += parseFloat(r.avail || '0');
          }
        }
      }
      const hasRTO = rtoAvail > 0;
      const occupiedUnits = hasRTO ? Math.round(rtoOcc)              : filteredData.filter(u => u.occupiedYN).length;
      const vacantUnits   = hasRTO ? Math.round(rtoAvail - rtoOcc)   : totalUnits - occupiedUnits;
      const occupancyRate = hasRTO ? rtoOcc / rtoAvail               : (totalUnits > 0 ? filteredData.filter(u => u.occupiedYN).length / totalUnits : 0);

      const avgStreet = filteredData.reduce((s, u) => s + (u.streetRate || 0), 0) / totalUnits;
      const avgInHouse = filteredData.reduce((s, u) => s + (u.inHouseRate || 0), 0) / totalUnits;

      // ── Modulo & AI rates already generated ───────────────────────────────
      const withModulo = filteredData.filter(u => u.moduloSuggestedRate && u.moduloSuggestedRate > 0);
      const withAI = filteredData.filter(u => u.aiSuggestedRate && u.aiSuggestedRate > 0);
      const avgModulo = withModulo.length
        ? withModulo.reduce((s, u) => s + u.moduloSuggestedRate!, 0) / withModulo.length : null;
      const avgAI = withAI.length
        ? withAI.reduce((s, u) => s + u.aiSuggestedRate!, 0) / withAI.length : null;
      const moduloVsStreetPct = avgModulo && avgStreet
        ? ((avgModulo - avgStreet) / avgStreet * 100) : null;
      const aiVsStreetPct = avgAI && avgStreet
        ? ((avgAI - avgStreet) / avgStreet * 100) : null;
      const aiVsModuloPct = avgAI && avgModulo
        ? ((avgAI - avgModulo) / avgModulo * 100) : null;

      // Vacant units where Modulo suggests higher than current street rate
      const vacantWithUpside = withModulo.filter(u =>
        !u.occupiedYN && u.moduloSuggestedRate! > (u.streetRate || 0)
      );

      // ── Attribute rating breakdown ─────────────────────────────────────────
      const countRatings = (field: keyof typeof filteredData[0]) => {
        const A = filteredData.filter(u => u[field] === 'A').length;
        const B = filteredData.filter(u => u[field] === 'B').length;
        const C = filteredData.filter(u => u[field] === 'C').length;
        const unrated = filteredData.filter(u => !u[field]).length;
        return { A, B, C, unrated };
      };
      const locRatings  = countRatings('locationRating');
      const sizeRatings = countRatings('sizeRating');
      const viewRatings = countRatings('viewRating');
      const renRatings  = countRatings('renovationRating');
      const amenRatings = countRatings('amenityRating');
      const fullyUnrated = filteredData.filter(u =>
        !u.locationRating && !u.sizeRating && !u.viewRating && !u.renovationRating && !u.amenityRating
      ).length;
      const heavilyC = filteredData.filter(u => {
        const cs = [u.locationRating, u.sizeRating, u.viewRating, u.renovationRating, u.amenityRating]
          .filter(Boolean);
        return cs.length > 0 && cs.filter(r => r === 'C').length / cs.length >= 0.6;
      }).length;

      // ── Service line & room type breakdown ────────────────────────────────
      const slBreakdown: Record<string, number> = {};
      filteredData.forEach(u => { const sl = u.serviceLine || 'Unknown'; slBreakdown[sl] = (slBreakdown[sl] || 0) + 1; });
      const rtRates: Record<string, { total: number; count: number; modulo: number; moduloCount: number }> = {};
      filteredData.forEach(u => {
        const rt = u.roomType || 'Unknown';
        if (!rtRates[rt]) rtRates[rt] = { total: 0, count: 0, modulo: 0, moduloCount: 0 };
        rtRates[rt].total += u.streetRate || 0;
        rtRates[rt].count += 1;
        if (u.moduloSuggestedRate) { rtRates[rt].modulo += u.moduloSuggestedRate; rtRates[rt].moduloCount += 1; }
      });

      // ── Competitor context ─────────────────────────────────────────────────
      const competitorRates = filteredCompetitors.map(c => c.streetRate).filter(Boolean) as number[];
      const avgCompRate = competitorRates.length
        ? competitorRates.reduce((s, r) => s + r, 0) / competitorRates.length : null;
      const marketSentiment = marketDataCache.lastMonthReturnPct > 1 ? 'bullish' : marketDataCache.lastMonthReturnPct < -1 ? 'bearish' : 'neutral';

      // ── Build prompt sections ──────────────────────────────────────────────
      const scopeStr = [location && `Location: ${location}`, serviceLine && `Service Line: ${serviceLine}`]
        .filter(Boolean).join(' | ') || 'All locations & service lines';

      const rateSection = [
        `- Street rate avg: $${Math.round(avgStreet).toLocaleString()}`,
        `- In-house rate avg: $${Math.round(avgInHouse).toLocaleString()}`,
        avgModulo ? `- **Modulo suggested rate** (${withModulo.length}/${totalUnits} units): $${Math.round(avgModulo).toLocaleString()} (${moduloVsStreetPct! >= 0 ? '+' : ''}${moduloVsStreetPct!.toFixed(1)}% vs street)` : '- Modulo rates: not yet calculated',
        avgAI ? `- **AI suggested rate** (${withAI.length}/${totalUnits} units): $${Math.round(avgAI).toLocaleString()} (${aiVsStreetPct! >= 0 ? '+' : ''}${aiVsStreetPct!.toFixed(1)}% vs street; ${aiVsModuloPct! >= 0 ? '+' : ''}${aiVsModuloPct!.toFixed(1)}% vs Modulo)` : '- AI rates: not yet calculated',
        vacantWithUpside.length ? `- Vacant units where Modulo rate > current street: ${vacantWithUpside.length} (avg upside: $${Math.round(vacantWithUpside.reduce((s, u) => s + (u.moduloSuggestedRate! - (u.streetRate || 0)), 0) / vacantWithUpside.length).toLocaleString()}/unit)` : '',
      ].filter(Boolean).join('\n');

      const attrSection = [
        `- Location ratings — A: ${locRatings.A}, B: ${locRatings.B}, C: ${locRatings.C}, unrated: ${locRatings.unrated}`,
        `- Size ratings    — A: ${sizeRatings.A}, B: ${sizeRatings.B}, C: ${sizeRatings.C}, unrated: ${sizeRatings.unrated}`,
        `- View ratings    — A: ${viewRatings.A}, B: ${viewRatings.B}, C: ${viewRatings.C}, unrated: ${viewRatings.unrated}`,
        `- Renovation      — A: ${renRatings.A}, B: ${renRatings.B}, C: ${renRatings.C}, unrated: ${renRatings.unrated}`,
        `- Amenity         — A: ${amenRatings.A}, B: ${amenRatings.B}, C: ${amenRatings.C}, unrated: ${amenRatings.unrated}`,
        `- Units with NO attribute ratings at all: ${fullyUnrated} (these get zero attribute pricing lift)`,
        heavilyC ? `- Units rated ≥60% C across attributes: ${heavilyC} (candidates for re-evaluation or discount positioning)` : '',
      ].filter(Boolean).join('\n');

      const weightsSection = weights ? [
        `- Occupancy Pressure: ${weights.occupancyPressure}`,
        `- Days Vacant Decay: ${weights.daysVacantDecay}`,
        `- Room Attributes: ${weights.roomAttributes}`,
        `- Seasonality: ${weights.seasonality}`,
        `- Competitor Rates: ${weights.competitorRates}`,
        `- Stock Market: ${weights.stockMarket}`,
        `- Inquiry/Tour Volume: ${weights.inquiryTourVolume}`,
      ].join('\n') : '- (No pricing weights configured — using defaults)';

      const targetsSection = revenueTargets.length
        ? revenueTargets.map(t => `- ${t.serviceLine || 'All SLs'}: ${t.targetGrowthPercent !== undefined && t.targetGrowthPercent !== null ? `${(Number(t.targetGrowthPercent) * 100).toFixed(1)}% growth target` : 'no target set'}`).join('\n')
        : '- No revenue growth targets saved yet';

      const roomTypeSection = Object.entries(rtRates)
        .map(([rt, d]) => {
          const avgSt = Math.round(d.total / d.count);
          const avgMod = d.moduloCount ? Math.round(d.modulo / d.moduloCount) : null;
          return `- ${rt}: street $${avgSt.toLocaleString()}${avgMod ? `, Modulo $${avgMod.toLocaleString()} (${((avgMod - avgSt) / avgSt * 100).toFixed(1)}%)` : ''}`;
        }).join('\n');

      const competitorSection = avgCompRate
        ? `- ${filteredCompetitors.length} competitors tracked | avg market rate: $${Math.round(avgCompRate).toLocaleString()} | our street rate is ${avgStreet >= avgCompRate ? '+' : ''}${((avgStreet - avgCompRate) / avgCompRate * 100).toFixed(1)}% vs market`
        : `- ${filteredCompetitors.length} competitors tracked (no rate data)`;

      const prompt = `You are analyzing real data from the Modulo Revenue Management platform for a senior living portfolio. Your job is to provide specific, actionable recommendations grounded in the numbers below.

**SCOPE: ${scopeStr}**
Units: ${totalUnits} total | ${occupiedUnits} occupied (${(occupancyRate * 100).toFixed(1)}%) | ${vacantUnits} vacant (${longVacant} vacant 30+ days)

---

**MODULO & AI RATE PERFORMANCE**
${rateSection}

**ROOM TYPE BREAKDOWN**
${roomTypeSection}

**SERVICE LINE MIX**
${Object.entries(slBreakdown).map(([sl, n]) => `- ${sl}: ${n} units`).join('\n')}

**UNIT ATTRIBUTE RATINGS**
${attrSection}

**CURRENT PRICING WEIGHTS**
${weightsSection}

**REVENUE GROWTH TARGETS**
${targetsSection}

**COMPETITOR CONTEXT**
${competitorSection}
Market sentiment: ${marketSentiment}

---

Write 5 specific recommendations using this exact format:
- Use **bold text** for each recommendation heading
- Use "- " bullet points for supporting details under each heading
- Be quantitative — reference the actual dollar amounts and percentages above
- Do NOT be generic. Every recommendation must reference the specific data provided.

Focus areas (in order):
1. Whether to adopt the Modulo or AI suggested rates — which is more appropriate and why, given occupancy and market position
2. Specific units or room types that should be re-attributed (change A/B/C ratings) to better capture pricing lift — call out the unrated units
3. Attribute pricing range expansion — should the attributesMin/Max guardrail be widened or narrowed based on the rating spread?
4. Pricing weight adjustments — which weights appear over- or under-calibrated given the current occupancy, vacancy, and competitor data?
5. Revenue target alignment — are the current targets achievable given Modulo/AI rate levels, and what changes would close any gap?`;

      const text = await callClaudeThenGPT(
        'You are a senior living revenue management expert. Always respond in markdown with **bold** headers and "- " bullet points. Be specific and quantitative. Never give generic advice.',
        prompt,
        'Format your response using **bold** for each recommendation heading and "- " bullet points for supporting details. Reference specific dollar amounts and percentages from the data. Keep each section tight and actionable.',
        { label: 'ai-insights', claudeMaxTokens: 1500, gptMaxTokens: 1200 }
      );

      // Persist the generated insight to the database
      const loc = location || 'all';
      const sl = serviceLine || 'all';
      await storage.upsertAiInsight(clientId, loc, sl, text);

      res.json({
        ok: true,
        text,
        filters: { location, serviceLine },
        context: { totalUnits, occupancyRate, competitorCount: filteredCompetitors.length }
      });

    } catch (error) {
      res.status(500).json({ error: `AI analysis failed: ${error.message}` });
    }
  });

  // Fetch stored AI insight for a given filter combination
  app.get("/api/ai/insights", async (req: any, res) => {
    try {
      const clientId = req.clientId || 'demo';
      const location = (req.query.location as string) || 'all';
      const serviceLine = (req.query.serviceLine as string) || 'all';
      const row = await storage.getAiInsight(clientId, location, serviceLine);
      if (!row) return res.json({ found: false });
      res.json({ found: true, content: row.content, generatedAt: row.generatedAt, updatedAt: row.updatedAt });
    } catch (error) {
      res.status(500).json({ error: `Failed to fetch insight: ${error.message}` });
    }
  });

  // ── AI Chat endpoint ─────────────────────────────────────────────────────
  app.post("/api/ai/chat", async (req: any, res) => {
    try {
      const clientId = req.clientId || 'demo';
      const { message, location, serviceLine, history = [] } = req.body || {};
      if (!message?.trim()) return res.status(400).json({ error: 'message is required' });

      // Detect portfolio-wide questions asked while a specific filter is active
      const broadKeywords = /\b(portfolio|all locations|across all|every campus|overall|company.wide|enterprise|all campuses|entire portfolio|whole portfolio|all facilities)\b/i;
      const filtersActive = (location && location !== 'all') || (serviceLine && serviceLine !== 'all');
      const suggestClearFilters = filtersActive && broadKeywords.test(message);

      // ── Fetch data (same as /api/ai/suggest) ─────────────────────────────
      const latestMonthResult = await db
        .select({ uploadMonth: rentRollData.uploadMonth })
        .from(rentRollData)
        .where(and(sql`${rentRollData.uploadMonth} IS NOT NULL`, eq(rentRollData.clientId, clientId)))
        .orderBy(sql`${rentRollData.uploadMonth} DESC`)
        .limit(1);
      const latestMonth = latestMonthResult[0]?.uploadMonth || '2026-05';

      let allData = await storage.getRentRollDataByMonth(latestMonth, clientId);
      let filteredData = allData;
      if (location && location !== 'all') filteredData = filteredData.filter(u => u.location === location);
      if (serviceLine && serviceLine !== 'all') filteredData = filteredData.filter(u => u.serviceLine === serviceLine);

      const totalUnits = filteredData.length;
      const longVacant = filteredData.filter(u => !u.occupiedYN && (u.daysVacant || 0) > 30).length;
      const avgStreet = totalUnits > 0 ? filteredData.reduce((s, u) => s + (u.streetRate || 0), 0) / totalUnits : 0;

      const withModulo = filteredData.filter(u => u.moduloSuggestedRate && u.moduloSuggestedRate > 0);
      const withAI = filteredData.filter(u => u.aiSuggestedRate && u.aiSuggestedRate > 0);
      const avgModulo = withModulo.length ? withModulo.reduce((s, u) => s + u.moduloSuggestedRate!, 0) / withModulo.length : null;
      const avgAI = withAI.length ? withAI.reduce((s, u) => s + u.aiSuggestedRate!, 0) / withAI.length : null;

      // ── Authoritative occupancy from room_type_occupancy_history ──────────
      // Query grouped by (location_name, service_line) so we can build per-campus
      // and per-SL occupancy breakdowns from the physical-room counts.
      const chatMY = latestMonth
        ? { year: parseInt(latestMonth.slice(0, 4)), month: parseInt(latestMonth.slice(5, 7)) }
        : null;
      // Map: "campus||sl-token" -> { occ, avail }
      const rtoMapChat = new Map<string, { occ: number; avail: number }>();
      let rtoTotOcc = 0, rtoTotAvail = 0;
      if (chatMY) {
        const chatRtoP: any[] = [clientId, chatMY.year, chatMY.month];
        const chatLocW = (location && location !== 'all')
          ? ` AND location_name = $${chatRtoP.push(location)}` : '';
        const chatRtoRes = await pool.query(
          `SELECT location_name, service_line,
                  SUM(occ_units) AS occ, SUM(available_units) AS avail
           FROM room_type_occupancy_history
           WHERE client_id=$1 AND year=$2 AND month=$3${chatLocW}
           GROUP BY location_name, service_line`,
          chatRtoP
        );
        for (const r of chatRtoRes.rows) {
          const camp  = String(r.location_name || '');
          const o     = parseFloat(r.occ   || '0');
          const av    = parseFloat(r.avail || '0');
          const toks  = String(r.service_line || '').split(',').map((t: string) => t.trim());
          for (const tok of toks) {
            if (serviceLine && serviceLine !== 'all' && tok !== serviceLine) continue;
            const key = `${camp}||${tok}`;
            const e   = rtoMapChat.get(key) || { occ: 0, avail: 0 };
            e.occ   += o;
            e.avail += av;
            rtoMapChat.set(key, e);
            rtoTotOcc   += o;
            rtoTotAvail += av;
          }
        }
      }
      const chatHasRTO = rtoTotAvail > 0;
      const occupiedUnits = chatHasRTO ? Math.round(rtoTotOcc)             : filteredData.filter(u => u.occupiedYN).length;
      const vacantUnits   = chatHasRTO ? Math.round(rtoTotAvail - rtoTotOcc) : totalUnits - occupiedUnits;
      const occupancyRate = chatHasRTO ? rtoTotOcc / rtoTotAvail           : (totalUnits > 0 ? filteredData.filter(u => u.occupiedYN).length / totalUnits : 0);
      const avgInHouse    = totalUnits > 0 ? filteredData.filter(u => u.occupiedYN).reduce((s, u) => s + (u.inHouseRate || 0), 0) / Math.max(1, occupiedUnits) : 0;

      const pct = (occ: number, tot: number) => (tot ? (100 * occ / tot).toFixed(1) : '0.0');

      // Per-service-line occupancy — prefer RTO, fall back to rent-roll
      let slOccStr: string;
      if (chatHasRTO) {
        const slTotals = new Map<string, { occ: number; avail: number }>();
        for (const [key, v] of rtoMapChat) {
          const sl = key.split('||')[1] || 'Unknown';
          const e  = slTotals.get(sl) || { occ: 0, avail: 0 };
          e.occ   += v.occ;
          e.avail += v.avail;
          slTotals.set(sl, e);
        }
        slOccStr = Array.from(slTotals.entries())
          .sort((a, b) => a[0].localeCompare(b[0]))
          .map(([sl, v]) => `${sl}: ${Math.round(v.occ)}/${Math.round(v.avail)} (${pct(v.occ, v.avail)}%)`)
          .join(', ');
      } else {
        const slOcc: Record<string, { total: number; occupied: number }> = {};
        filteredData.forEach(u => {
          const sl = u.serviceLine || 'Unknown';
          if (!slOcc[sl]) slOcc[sl] = { total: 0, occupied: 0 };
          slOcc[sl].total++;
          if (u.occupiedYN) slOcc[sl].occupied++;
        });
        slOccStr = Object.entries(slOcc)
          .sort((a, b) => a[0].localeCompare(b[0]))
          .map(([sl, o]) => `${sl}: ${o.occupied}/${o.total} (${pct(o.occupied, o.total)}%)`)
          .join(', ');
      }

      // Per-campus x service-line occupancy — prefer RTO, fall back to rent-roll
      const campusSl = new Map<string, Map<string, { occ: number; avail: number }>>();
      if (chatHasRTO) {
        for (const [key, v] of rtoMapChat) {
          const [camp, sl] = key.split('||');
          if (!campusSl.has(camp)) campusSl.set(camp, new Map());
          campusSl.get(camp)!.set(sl || 'Unknown', v);
        }
      } else {
        for (const u of filteredData) {
          const camp = u.location || 'Unknown';
          const sl   = u.serviceLine || 'Unknown';
          if (!campusSl.has(camp)) campusSl.set(camp, new Map());
          const m = campusSl.get(camp)!;
          const e = m.get(sl) || { occ: 0, avail: 0 };
          e.avail++;
          if (u.occupiedYN) e.occ++;
          m.set(sl, e);
        }
      }
      const campusCount = campusSl.size;
      const campusOccLines = Array.from(campusSl.entries())
        .sort((a, b) => a[0].localeCompare(b[0]))
        .map(([camp, slMap]) => {
          let cTot = 0, cOcc = 0;
          const parts = Array.from(slMap.entries())
            .sort((a, b) => a[0].localeCompare(b[0]))
            .map(([sl, v]) => {
              cTot += v.avail; cOcc += v.occ;
              return `${sl} ${Math.round(v.occ)}/${Math.round(v.avail)} (${pct(v.occ, v.avail)}%)`;
            });
          return `${camp} [overall ${pct(cOcc, cTot)}%]: ${parts.join(', ')}`;
        });

      let allCompetitors = await storage.getCompetitors(clientId);
      let filteredCompetitors = location && location !== 'all'
        ? allCompetitors.filter(c => c.location === location) : allCompetitors;
      const competitorRates = filteredCompetitors.map(c => c.streetRate).filter(Boolean) as number[];
      const avgCompRate = competitorRates.length
        ? competitorRates.reduce((s, r) => s + r, 0) / competitorRates.length : null;

      const scopeStr = [location && location !== 'all' && `Location: ${location}`, serviceLine && serviceLine !== 'all' && `Service Line: ${serviceLine}`]
        .filter(Boolean).join(' | ') || 'All locations & service lines (portfolio-wide)';

      const dataContext = `
**DATA SCOPE: ${scopeStr}**
Units: ${totalUnits} total | ${occupiedUnits} occupied (${(occupancyRate * 100).toFixed(1)}%) | ${vacantUnits} vacant (${longVacant} vacant 30+ days)
Avg street rate: $${Math.round(avgStreet).toLocaleString()} | Avg in-house rate: $${Math.round(avgInHouse).toLocaleString()}
${avgModulo ? `Modulo suggested avg: $${Math.round(avgModulo).toLocaleString()} (${withModulo.length} units)` : 'Modulo rates: not calculated'}
${avgAI ? `AI suggested avg: $${Math.round(avgAI).toLocaleString()} (${withAI.length} units)` : 'AI rates: not calculated'}
${avgCompRate ? `Market avg competitor rate: $${Math.round(avgCompRate).toLocaleString()} (${filteredCompetitors.length} competitors)` : 'No competitor rate data'}
Campuses in scope: ${campusCount}
Service line occupancy (across scope): ${slOccStr}

CAMPUS x SERVICE LINE OCCUPANCY (latest month — use this for any per-campus or per-service-line occupancy question; format is "<service line> <occupied>/<total beds> (<occupancy %>)"):
${campusOccLines.join('\n')}
`.trim();

      const systemPrompt = `You are an expert revenue management advisor for senior living facilities, working inside the Modulo platform. Answer the user's question conversationally and specifically, grounded in the data context provided. You have access to the full campus-by-service-line occupancy breakdown for the current scope — when asked to count, filter, or compare campuses or service lines by occupancy (e.g. "how many campuses have AL/MC under 90%"), compute the answer directly from the CAMPUS x SERVICE LINE OCCUPANCY table and list the qualifying campuses. Be concise (2-5 sentences unless a detailed breakdown is asked for); for counting questions give the count first, then the supporting campuses. Use **bold** for key figures. Never give generic advice or claim the data is unavailable when it is present in the context — always reference the actual numbers.`;

      const userTurn = `Here is the current portfolio data for your reference:\n${dataContext}\n\nUser question: ${message}`;

      // Build messages array for multi-turn conversation
      const messages: any[] = [
        { role: 'system', content: systemPrompt },
        ...history.slice(-8).map((h: any) => ({ role: h.role, content: h.content })),
        { role: 'user', content: userTurn },
      ];

      const openai = (await import('openai')).default;
      const client = new openai();
      const completion = await client.chat.completions.create({
        model: 'gpt-4o',
        messages,
        max_tokens: 600,
        temperature: 0.7,
      });
      const reply = completion.choices[0]?.message?.content?.trim() || 'Sorry, I could not generate a response.';

      res.json({ reply, suggestClearFilters });
    } catch (error: any) {
      res.status(500).json({ error: `Chat failed: ${error.message}` });
    }
  });

